import {STORAGE_KEY,MAX_REFERENCES,traits,uid,plainText,normalizeReference,createOutline,createVariants,fingerprint,editDraft,validateApproval,planDraft,deleteStory,freshState,examples,readState,ensureProfile,addFeedback,proposeStyle,applyStyle,exportSkill} from './core.js';
const $=(s,p=document)=>p.querySelector(s);
const esc=(v='')=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={book:'M4 3h7c2 0 3 1 3 2v16c0-2-2-3-4-3H4z M20 3h-6v18c0-2 2-3 4-3h2z',inbox:'M4 4h16v16H4z M4 13h5l2 3h2l2-3h5',pen:'m14 4 6 6 M4 20l4-1L20 7a2 2 0 0 0-4-4L4 15z',spark:'m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5z',calendar:'M4 5h16v16H4z M8 2v6 M16 2v6 M4 11h16',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',plus:'M12 5v14 M5 12h14',arrow:'M4 12h16 M14 6l6 6-6 6',mic:'M9 5a3 3 0 0 1 6 0v7a3 3 0 0 1-6 0z M6 10v2a6 6 0 0 0 12 0v-2 M12 18v4 M8 22h8',lock:'M6 11h12v10H6z M8 11V6a4 4 0 0 1 8 0v5',check:'m5 12 4 4L19 6',close:'m6 6 12 12 M18 6 6 18',trash:'M4 6h16 M9 6V3h6v3 M6 6l1 15h10l1-15 M10 10v7 M14 10v7',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',info:'M12 11v6 M12 7h.01 M22 12a10 10 0 1 0-20 0 10 10 0 0 0 20 0',chevron:'m9 5 7 7-7 7',link:'m9 15 6-6 M9 8l3-3a4 4 0 0 1 6 6l-3 3 M15 16l-3 3a4 4 0 0 1-6-6l3-3',copy:'M8 8h12v13H8z M16 8V3H3v13h5',chat:'M3 4h18v13H8l-5 4z',heart:'M12 20 3 11a5 5 0 0 1 9-5 5 5 0 0 1 9 5z',history:'M4 5v6h6 M4 11a8 8 0 1 1 2 7 M12 7v6l4 2',shield:'m12 2 8 3v7c0 5-8 10-8 10S4 17 4 12V5z M8 12l3 3 5-6',upload:'M12 17V3 M7 8l5-5 5 5 M4 17v4h16v-4',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7 M15 12a3 3 0 1 0-6 0 3 3 0 0 0 6 0',flower:'M12 12C-4-5 5-9 12 5c7-14 16-10 0 7 17-16 21-7 7 0 14 7 10 16-7 0 16 17 7 21 0 7-7 14-16 10 0-7-17 16-21 7-7 0-14-7-10-16 7 0'};
const icon=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.45" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.book}"/></svg>`;
let initialState;try{initialState=readState(localStorage);}catch{initialState=freshState();}
let state=ensureProfile(initialState),route='stories',selectedDraft=null,preview='plain',filter='all',calendarMonth=new Date(),onboardStep=0,storageFailed=false,modalReturnFocus=null,mediaRecorder=null,mediaStream=null,recordChunks=[],recordedBlob=null,recordTimer=null,objectUrls=[],recordEpoch=0;
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));storageFailed=false;}catch{storageFailed=true;toast('Storage is full or blocked. Export your workspace before leaving.');}}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('visible'),4500);}
const dateLabel=(s)=>new Date(s).toLocaleDateString(undefined,{month:'short',day:'numeric'});
const initials=()=>state.profile.name?state.profile.name.split(/\s/).map(x=>x[0]).slice(0,2).join('').toUpperCase():'YOU';
const names={stories:'Story inbox',studio:'Writing studio',style:'Your voice',calendar:'Content calendar',settings:'Settings'};
function shell(){route=location.hash.slice(1).split('/')[0]||'stories';if(!names[route])route='stories';$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-icon">${icon('book')}</span>storybank<span style="color:#9ca98c;font-size:22px">.</span></div><div class="workspace"><div class="avatar">${esc(initials())}</div><div><strong>${esc(state.profile.name||'Your workspace')}</strong><small>Personal writing space</small></div></div><div class="section-label">Your creative space</div><nav class="nav" aria-label="Main navigation">${[['stories','inbox'],['studio','pen'],['style','spark'],['calendar','calendar'],['settings','settings']].map(([key,i])=>`<a href="#${key}" ${route===key?'aria-current="page"':''} class="${route===key?'active':''}">${icon(i)}${names[key]}${key==='stories'?`<span>${state.stories.length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="local-card"><strong><span class="dot"></span> A safe place to start</strong><p>This prototype saves on this browser only. Nothing is posted to LinkedIn.</p></div><button class="bottom-link" data-action="onboard">${icon('info')}Take a quick tour</button></div></aside><div class="main-wrap"><header class="topbar"><div class="crumb">Your workspace <strong>/ ${names[route]}</strong></div><div class="top-right"><span class="badge neutral">LOCAL PROTOTYPE</span><button class="text-btn" data-action="privacy">${icon('lock')}Your data</button><div class="avatar">${esc(initials())}</div></div></header><main id="main" class="main" tabindex="-1">${storageFailed?'<div class="storage-error">Browser storage is unavailable. Export your work before closing this page.</div>':''}${({stories:storiesView,studio:studioView,style:styleView,calendar:calendarView,settings:settingsView})[route]()}</main></div></div>`;if(route==='studio')updatePreview();}
function heading(eyebrow,title,desc,action=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`;}
function notice(text,type=''){return `<div class="notice ${type}">${icon('info')}<span>${text}</span></div>`;}
function storiesView(){const stories=state.stories.filter(s=>filter==='all'||(filter==='mine'&&!s.demo)||(filter==='voice'&&s.audioId));return `${heading('Good stories start here','Make something of your moments.','A small observation today. A post that sounds like you tomorrow.')}<div class="welcome-grid"><section class="capture-card"><div class="card-top"><div class="card-title"><span class="icon-square">${icon('pen')}</span>What happened recently?</div><span class="badge neutral">1. CAPTURE</span></div><textarea id="quick-note" class="capture-input" aria-label="Your story" placeholder="A conversation that stayed with you. Something you learned. A tiny win. Start anywhere…" maxlength="12000"></textarea><div class="capture-bottom"><span class="capture-hint">${icon('lock')}Only saved in this browser</span><div class="actions"><button class="btn secondary small" data-action="voice">${icon('mic')}Voice note</button><button class="btn small" data-action="quick-save">Save this story ${icon('arrow')}</button></div></div></section><aside class="prompt-card"><div class="eyebrow" style="color:#8b7e9f">A little inspiration</div><h2>What did you learn<br>the hard way?</h2><p>The useful details are often hiding in the everyday stuff.</p><button class="text-btn" data-action="prompt">Use this prompt ${icon('arrow')}</button><div class="prompt-flower">${icon('flower')}</div></aside></div><div class="row-heading"><h2>Your story shelf <span class="muted" style="font-size:12px;margin-left:6px">${state.stories.length}</span></h2><div class="filters"><button class="chip ${filter==='all'?'active':''}" data-filter="all">All stories</button><button class="chip ${filter==='mine'?'active':''}" data-filter="mine">My stories</button><button class="chip ${filter==='voice'?'active':''}" data-filter="voice">Voice notes</button></div></div><div class="story-grid">${stories.length?stories.map(storyCard).join(''):`<div class="empty"><h3>There’s a story in your everyday.</h3><p>Save a moment above, or try two clearly labelled examples to see how the studio works.</p><button class="btn secondary" data-action="load-examples">Explore with examples ${icon('arrow')}</button></div>`}</div><div class="bottom-note">${icon('spark')}Your experiences are the source. Your writing preferences shape the telling.</div>`;}
function storyCard(s){return `<article class="story-card"><div class="card-top no-margin"><span class="badge ${s.demo?'purple':''}">${s.demo?'DEMO EXAMPLE':s.audioId?'VOICE NOTE':esc(s.tag||'Your story')}</span><button class="icon-btn" aria-label="Open ${esc(s.title)}" data-action="view-story" data-id="${s.id}">${icon('eye')}</button></div><h3>${esc(s.title)}</h3><p class="story-excerpt">${esc(s.body||'Audio saved. Add your own transcript before drafting.')}</p><footer><small>${dateLabel(s.createdAt)}</small><button class="text-btn" data-action="draft-variants" data-id="${s.id}">Shape a post ${icon('arrow')}</button></footer></article>`;}
function studioView(){const requested=location.hash.split('/')[1];if(requested&&state.drafts.some(d=>d.id===requested))selectedDraft=requested;let d=state.drafts.find(d=>d.id===selectedDraft)||state.drafts[0];selectedDraft=d?.id||null;return `${heading('From experience to expression','Words that feel like you.','Choose a version, make it yours, then review it.',`<button class="btn secondary" data-action="choose-story">${icon('plus')}Start from a story</button>`)}${notice('Template previews, not AI writing. Every version starts with your own words. No model is connected.')} ${d?`<div class="studio-grid"><aside class="draft-list"><div class="section-label" style="margin:0 0 12px">Your drafts · ${state.drafts.length}</div>${state.drafts.map(x=>`<button class="draft-item ${x.id===d.id?'active':''}" data-action="select-draft" data-id="${x.id}"><strong>${esc(x.title)}</strong><span class="badge ${x.approval?'':'neutral'}">${x.approval?'Reviewed':'In progress'}</span><small>${esc(x.variant||'Your outline')} · ${dateLabel(x.createdAt)}</small></button>`).join('')}</aside><section><div class="editor-card"><div class="editor-bar"><button class="icon-btn" data-action="format-bold" aria-label="Mark selection bold for workspace preview"><b>B</b></button><button class="icon-btn" data-action="format-italic" aria-label="Mark selection italic for workspace preview"><i>I</i></button><span class="editor-label">Saved on this browser</span></div><textarea id="draft-body" class="editor-area" aria-label="Edit your draft" maxlength="16000">${esc(d.body)}</textarea><div class="editor-footer"><span id="character-count"></span><button class="text-btn" data-action="feedback" data-id="${d.id}">${icon('chat')}How does it feel?</button></div><div class="approval-section"><label class="check"><input id="reviewed" type="checkbox" ${d.reviewed?'checked':''}>I’ve checked the facts, permissions, and wording. This is the version I want to use.</label><div class="approval-actions"><button class="btn small" data-action="approve" id="approve-btn">${icon('check')}${d.approval?'Version reviewed':'Approve this version'}</button><button class="btn secondary small" data-action="plan" id="plan-btn" ${!d.approval?'disabled':''}>${icon('calendar')}Plan a date</button><button class="btn secondary small" data-action="copy">${icon('copy')}Copy text</button></div><div id="approval-note" class="preview-note">${d.approval?'This exact plain-text version has been reviewed. Editing it requires a new review.':'Nothing publishes automatically. Approval is stored locally for this exact version.'}</div></div></div><p class="preview-note">Bold and italic are workspace formatting only. Ordinary LinkedIn feed posts use plain text. Copy and export remove these markers.</p></section><aside class="studio-preview"><div class="preview-toggle"><button data-preview="plain" class="${preview==='plain'?'active':''}">LinkedIn-style preview</button><button data-preview="rich" class="${preview==='rich'?'active':''}">Workspace formatting</button></div><div class="post-preview"><div class="post-author"><div class="avatar">${esc(initials())}</div><div><strong>${esc(state.profile.name||'Your name')}</strong><small>${esc(state.profile.headline||'Your headline goes here')}</small><small>Preview only · ◉</small></div></div><div id="post-body" class="post-body"></div><div class="post-actions"><span>${icon('heart')}Like</span><span>${icon('chat')}Comment</span><span>${icon('arrow')}Repost</span></div></div><details class="source-panel"><summary>View the source story</summary><p>${esc(d.sourceSnapshot)}</p></details><p class="preview-note">Source-linked, not automatically fact-checked. Your edits may add claims; review them against what actually happened.</p><button class="text-btn" data-action="export-draft">${icon('download')}Download plain text</button></aside></div>`:`<div class="empty"><h3>Good posts begin with something real.</h3><p>Pick a saved story. You’ll get three template previews to edit and give feedback on.</p><button class="btn" data-action="choose-story">Choose a story ${icon('arrow')}</button></div>`}`;}
function styleView(){return `${heading('A voice of your own','Your voice. Not a copy.','Your preferences and feedback stay in your personal writing profile.',`<button class="btn secondary" data-action="export-skill">${icon('download')}Download my profile</button>`)}<div class="grid-2"><section class="panel"><div class="panel-head"><h2>How you like to write</h2><span class="badge">Version ${state.styleVersion}</span></div><p>Start simple. Refine this after you try a few posts.</p><label class="field"><span>Your tone</span><select id="style-tone">${['Warm & grounded','Clear & practical','Thoughtful & reflective','Direct & confident'].map(t=>`<option ${t===state.style.tone?'selected':''}>${t}</option>`).join('')}</select><small>Saved for your profile. Tone rewriting needs a connected AI model.</small></label><label class="field"><span>Where should a post begin?</span><select id="style-structure"><option value="story" ${state.style.structure==='story'?'selected':''}>Start with the story</option><option value="lesson" ${state.style.structure==='lesson'?'selected':''}>Start with my story title</option></select></label><div class="field"><span>Pick the qualities you want</span><div class="tag-group">${traits.map(t=>`<button class="tag-toggle ${state.style.traits.includes(t)?'active':''}" data-trait="${t}" aria-pressed="${state.style.traits.includes(t)}">${t}</button>`).join('')}</div><small>Templates apply paragraph rhythm, starting point, and closing questions. Other traits are saved for future AI writing.</small></div><label class="field"><span>What should your writing avoid?</span><textarea id="style-avoid" maxlength="1500">${esc(state.style.avoid)}</textarea></label><button class="btn" data-action="save-style">Save my preferences ${icon('check')}</button><div class="style-summary">${icon('lock')} Just this browser’s personal workspace. In the production design, profiles and feedback are bound to each signed-in person, never pooled.</div></section><section class="panel"><div class="panel-head"><h2>People who inspire you</h2><span class="badge purple">${state.references.length} / ${MAX_REFERENCES}</span></div><p>Add up to 15 names or links, then describe what you like in your own words. Aim for 10–15 if that helps you find your style.</p>${notice('Names and links are bookmarks, not imported content. StoryBank does not scrape creators or claim to learn from their posts.')}<div>${state.references.length?state.references.map(r=>`<div class="reference"><div class="ref-icon">${esc(r.name[0])}</div><div class="reference-info"><strong>${esc(r.name)}</strong><p>${esc(r.notes||'Add your own description of what you like.')}</p>${r.url?`<a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">Open reference ↗</a>`:''}</div><button class="icon-btn" data-action="delete-reference" data-id="${r.id}" aria-label="Remove ${esc(r.name)}">${icon('close')}</button></div>`).join(''):'<div class="empty"><h3>Inspiration, with intention.</h3><p>“Short openings” or “specific lessons” is more useful than “write exactly like them.”</p></div>'}</div><button class="btn secondary spaced" data-action="add-reference" ${state.references.length>=15?'disabled':''}>${icon('plus')}Add a person</button></section><section class="panel"><div class="panel-head"><h2>Make it more you</h2><span class="badge neutral">${state.feedback.length} notes</span></div><p>Try three versions of a real story, say what works, and choose which changes to apply to your profile.</p><button class="btn secondary" data-action="choose-story">Try a writing session ${icon('arrow')}</button>${state.feedback.slice(-3).reverse().map(f=>`<div class="reference"><div class="reference-info"><strong>${f.rating==='like'?'Liked a version':f.rating==='dislike'?'Wanted a change':'Explained an edit'}</strong><p>${esc(f.note||f.reasons.join(', ')||'No extra notes.')}</p></div></div>`).join('')}</section><section class="panel"><div class="panel-head"><h2>Your profile history</h2>${icon('history')}</div><p>New preferences only affect future drafts. Existing drafts stay as you wrote them.</p>${state.styleHistory.slice(-4).reverse().map(h=>`<div class="reference"><div class="reference-info"><strong>Version ${h.version} ${h.version===state.styleVersion?'· current':''}</strong><p>${esc(h.reason)} · ${dateLabel(h.at)}</p></div>${h.version!==state.styleVersion?`<button class="text-btn" data-action="restore-style" data-version="${h.version}">Restore</button>`:''}</div>`).join('')}<button class="text-btn spaced" data-action="reset-style">Start again with default preferences</button></section></div>`;}
function calendarView(){const y=calendarMonth.getFullYear(),m=calendarMonth.getMonth(),first=new Date(y,m,1).getDay(),days=new Date(y,m+1,0).getDate(),today=new Date();const plans=state.plans.filter(p=>p.status==='planned').sort((a,b)=>Date.parse(a.timeISO)-Date.parse(b.timeISO));return `${heading('A little room for consistency','Give your stories a place.','Plan when you want to share. You stay in control.')} ${notice('Planning only. These dates do not publish posts or send reminders. Copy your final text to LinkedIn and use its native scheduler.','amber')}<div class="calendar-grid"><section class="calendar"><div class="calendar-head"><h2>${calendarMonth.toLocaleDateString(undefined,{month:'long',year:'numeric'})}</h2><div class="actions"><button class="icon-btn" data-action="prev-month" aria-label="Previous month">‹</button><button class="icon-btn" data-action="next-month" aria-label="Next month">›</button></div></div><div class="cal-week">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(x=>`<span>${x}</span>`).join('')}</div><div class="cal-cells">${Array.from({length:first},()=>'<div class="cal-day blank"></div>').join('')}${Array.from({length:days},(_,i)=>{let n=i+1,items=plans.filter(p=>{let d=new Date(p.timeISO);return d.getFullYear()===y&&d.getMonth()===m&&d.getDate()===n});return `<div class="cal-day ${today.getFullYear()===y&&today.getMonth()===m&&today.getDate()===n?'today':''}"><span>${n}</span>${items.map(p=>`<button class="cal-event" data-action="select-draft" data-id="${p.draftId}">${esc(state.drafts.find(d=>d.id===p.draftId)?.title||'Draft')}</button>`).join('')}</div>`;}).join('')}</div></section><aside class="panel"><h2 style="font-size:17px">Your next stories</h2><p>Times shown in ${esc(Intl.DateTimeFormat().resolvedOptions().timeZone)}.</p>${plans.length?plans.map(p=>`<div class="plan-card"><span class="badge ${Date.parse(p.timeISO)<Date.now()?'amber':''}">${Date.parse(p.timeISO)<Date.now()?'Date passed · not posted':'Locally planned'}</span><h3 style="margin-top:12px">${esc(state.drafts.find(d=>d.id===p.draftId)?.title||'Draft')}</h3><p>${esc(new Date(p.timeISO).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'}))}</p><div class="actions"><button class="text-btn" data-action="select-draft" data-id="${p.draftId}">Open post</button><button class="text-btn danger-text" data-action="cancel-plan" data-id="${p.id}">Cancel plan</button></div></div>`).join(''):'<div class="empty" style="padding:25px 12px"><h3 style="font-size:20px">Nothing planned yet.</h3><p>Review a draft, then choose a date.</p><a class="btn secondary small" href="#studio">Go to the studio</a></div>'}</aside></div>`;}
function settingsView(){return `${heading('Your workspace, your choice','Keep things clear.','Know what is saved, what is connected, and what is still a prototype.')}<div class="settings-grid"><section class="panel"><h2>Your profile</h2><label class="field"><span>Your name</span><input id="profile-name" value="${esc(state.profile.name)}" maxlength="80" placeholder="How should your preview look?"></label><label class="field"><span>Your headline</span><input id="profile-headline" value="${esc(state.profile.headline)}" maxlength="160" placeholder="What do you do?"></label><button class="btn" data-action="save-profile">Save profile</button></section><section class="panel"><h2>Connections</h2>${[['in','LinkedIn sign-in','Not configured. No LinkedIn password is collected.'],['pen','AI writing','Not connected. You are using labelled template previews.'],['mic','Voice transcription','Not connected. You can record and edit a transcript yourself.'],['calendar','Automatic publishing','Disabled. Requires approved API access and a production backend.']].map(([i,n,d])=>`<div class="integration"><div class="integration-icon">${i==='in'?'<b>in</b>':icon(i)}</div><div><strong>${n}</strong><p>${d}</p></div><span class="badge neutral">Not active</span></div>`).join('')}<button class="text-btn spaced" data-action="integration-details">What’s needed to connect? ${icon('arrow')}</button></section><section class="panel"><h2>Your data</h2><p>Text is saved in this browser’s local storage. Audio is saved in this browser’s IndexedDB. There is no account, sync, encryption-at-rest guarantee, or multi-user protection in this prototype. Avoid sensitive information, especially on shared devices.</p><p>No story text, audio, reference content, or feedback is sent to an AI provider or LinkedIn.</p><div class="actions"><button class="btn secondary" data-action="export-workspace">${icon('download')}Export text workspace</button><button class="btn secondary" data-action="export-skill">${icon('download')}Export writing profile</button></div><p class="preview-note">Text export does not include recordings. Download each recording from its story before clearing data.</p><hr class="divider"><button class="btn danger" data-action="delete-workspace">${icon('trash')}Delete this browser’s workspace</button></section><section class="panel"><h2>Built on a few promises</h2><div class="reference"><div class="icon-square">${icon('shield')}</div><div class="reference-info"><strong>Your facts remain yours</strong><p>References guide broad preferences, never invent your experiences.</p></div></div><div class="reference"><div class="icon-square">${icon('check')}</div><div class="reference-info"><strong>You review the final words</strong><p>Any edit clears approval and cancels that draft’s active plan.</p></div></div><div class="reference"><div class="icon-square">${icon('lock')}</div><div class="reference-info"><strong>No password sharing</strong><p>A future LinkedIn connection must use its official OAuth consent flow, with sign-in and publishing permissions handled separately.</p></div></div><p class="preview-note">Production security is a separate implementation, not a claim about this local preview. See the included security design and tests.</p></section></div>`;}
function openModal(title,subtitle,body,{wide=false}={}){closeModal(false);modalReturnFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="modal-title"><div><h2 id="dialog-title">${title}</h2><p>${subtitle}</p></div><button class="icon-btn" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div>${body}<p class="error" role="alert" id="modal-error"></p></section></div>`;document.body.style.overflow='hidden';requestAnimationFrame(()=>{$('.modal input:not([type=checkbox]), .modal textarea, .modal button')?.focus();});}
function closeModal(returnFocus=true){recordEpoch++;stopRecording();recordedBlob=null;objectUrls.forEach(u=>URL.revokeObjectURL(u));objectUrls=[];$('#modal-root').innerHTML='';document.body.style.overflow='';if(returnFocus)modalReturnFocus?.focus();}
function modalError(msg){const e=$('#modal-error');if(e)e.textContent=msg;else toast(msg);}
function onboard(){const steps=[{title:'Your stories have somewhere to go.',sub:'Welcome to StoryBank. Start with the real stuff.',body:`<div class="onboard-art"><div class="paper"></div><div class="paper"></div></div><p>Capture a moment, explore three ways to tell it, and teach your writing profile what feels like you.</p><div class="onboard-pills"><span>1 · Tell a story</span><span>2 · Make it yours</span><span>3 · Plan a date</span></div>${notice('This is a local prototype. No account is created, no AI is connected, and nothing is posted to LinkedIn.','green')}`},{title:'Make this space yours.',sub:'These details only appear in your local workspace and previews.',body:`<label class="field"><span>What should we call you?</span><input id="onboard-name" value="${esc(state.profile.name)}" maxlength="80" placeholder="Your name (optional)"></label><label class="field"><span>What kind of work do you do?</span><input id="onboard-headline" value="${esc(state.profile.headline)}" maxlength="160" placeholder="For example, designer, founder, or marketer"></label><p class="preview-note">Your personal profile is not shared with anyone. This browser prototype does not sign you in or protect against other people using the same browser.</p>`},{title:'Begin with something that happened.',sub:'A useful post does not need a big life lesson.',body:`<div class="recording"><strong>What did you do, what happened, and what did you learn?</strong><p>Keep the details you know. Leave out facts you are not sure about.</p></div><p>You can type a note or record your voice. Audio stays in this browser; automatic transcription is not connected.</p><div class="actions"><button class="btn secondary" data-action="finish-examples">Try example stories</button></div>`}][onboardStep];openModal(steps.title,steps.sub,`<div class="onboard-steps">${[0,1,2].map(i=>`<i class="${i<=onboardStep?'active':''}"></i>`).join('')}</div>${steps.body}<div class="actions">${onboardStep>0?'<button class="btn secondary" data-action="onboard-back">Back</button>':''}<button class="btn" data-action="onboard-next">${onboardStep===2?'Start my story':'Continue'} ${icon('arrow')}</button></div>`);}
function newStoryModal(body='',voice=false){openModal(voice?'Say it while it’s fresh.':'Keep this moment.','A few real details are enough to get started.',`<form id="story-form"><label class="field"><span>A short title</span><input name="title" required maxlength="100" placeholder="What is this story about?"></label>${voice?`<div class="recording" id="record-panel"><strong id="record-status">Ready when you are</strong><p>Microphone access is requested only when you press Record. Audio stays in this browser. No transcription service is connected.</p><div class="actions" style="justify-content:center;margin:0"><button type="button" class="btn secondary small" data-action="record" id="record-btn">${icon('mic')}Record</button><button type="button" class="btn secondary small" data-action="stop-record" id="stop-btn" disabled>Stop recording</button></div><div id="record-preview"></div></div>`:''}<label class="field"><span>${voice?'Your transcript or notes':'What happened?'}</span><textarea name="body" id="story-body" ${voice?'':'required'} maxlength="12000" rows="5" placeholder="What did you do? What happened? What did you learn?">${esc(body)}</textarea><small>${voice?'Write or paste your own transcript. Audio alone is saved, but a written note is needed for drafts.':'Use your own experience, or material you have permission to use.'}</small></label><label class="field"><span>A little context</span><select name="tag"><option>Work moment</option><option>Something learned</option><option>A small win</option><option>A personal reflection</option><option>An observation</option></select></label><label class="check"><input name="rights" type="checkbox" required>I confirm this is my experience or material I’m authorized to use. I’ve left out other people’s confidential information.</label><div class="actions"><button type="button" class="btn secondary" data-action="close-modal">Cancel</button><button type="submit" class="btn">Save my story ${icon('check')}</button></div></form>`);}
async function audioDb(){return new Promise((resolve,reject)=>{const q=indexedDB.open('storybank-public-audio',1);q.onupgradeneeded=()=>q.result.createObjectStore('recordings');q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);});}
async function audioOp(method,id,blob){const db=await audioDb();try{return await new Promise((resolve,reject)=>{const tx=db.transaction('recordings',method==='get'?'readonly':'readwrite');const store=tx.objectStore('recordings');let req=method==='put'?store.put(blob,id):method==='get'?store.get(id):method==='delete'?store.delete(id):store.clear();let value;req.onsuccess=()=>{value=req.result};tx.oncomplete=()=>resolve(value);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('Audio save was interrupted.'));});}finally{db.close();}}
async function record(){if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw Error('Recording is unavailable in this browser. Type your story instead.');if(mediaRecorder?.state==='recording')return;const btn=$('#record-btn');btn.disabled=true;const epoch=++recordEpoch;let stream;try{stream=await navigator.mediaDevices.getUserMedia({audio:true});if(epoch!==recordEpoch||!$('#record-panel')){stream.getTracks().forEach(t=>t.stop());return;}mediaStream=stream;const chunks=[];recordChunks=chunks;recordedBlob=null;const currentRecorder=new MediaRecorder(stream);mediaRecorder=currentRecorder;currentRecorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};currentRecorder.onstop=()=>{stream.getTracks().forEach(t=>t.stop());if(epoch!==recordEpoch)return;recordedBlob=new Blob(chunks,{type:currentRecorder.mimeType||'audio/webm'});mediaStream?.getTracks().forEach(t=>t.stop());mediaStream=null;clearInterval(recordTimer);if($('#record-panel')){$('#record-status').textContent='Recording ready. Add your transcript below.';$('#record-panel').classList.remove('active');$('#record-btn').disabled=false;$('#record-btn').textContent='Record again';$('#stop-btn').disabled=true;let url=URL.createObjectURL(recordedBlob);objectUrls.push(url);$('#record-preview').innerHTML=`<audio class="audio" controls src="${url}"></audio>`;}};mediaRecorder.start();let secs=0;$('#record-status').textContent='Recording · 0:00';$('#record-panel').classList.add('active');$('#stop-btn').disabled=false;recordTimer=setInterval(()=>{secs++;if($('#record-status'))$('#record-status').textContent=`Recording · ${Math.floor(secs/60)}:${String(secs%60).padStart(2,'0')}`;if(secs>=300)stopRecording();},1000);}catch(e){stream?.getTracks().forEach(t=>t.stop());if(btn)btn.disabled=false;throw Error(e.name==='NotAllowedError'?'Microphone permission was not granted. You can still type your story.':'Could not start the microphone. You can still type your story.');}}
function stopRecording(){if(mediaRecorder?.state==='recording')mediaRecorder.stop();mediaStream?.getTracks().forEach(t=>t.stop());clearInterval(recordTimer);}
async function viewStory(id){const s=state.stories.find(x=>x.id===id);if(!s)return;openModal(esc(s.title),s.demo?'Demo example, not your personal experience.':`Saved ${dateLabel(s.createdAt)}`,`${s.demo?notice('This is sample content. Replace it with your own experience before using it as a personal post.','amber'):''}<div id="saved-audio" data-story-id="${s.id}"></div><p style="white-space:pre-wrap;font-size:14px;line-height:1.9">${esc(s.body||'No written notes yet.')}</p>${s.audioId?`<button class="text-btn" data-action="add-transcript" data-id="${s.id}">Edit transcript ${icon('pen')}</button>`:''}<div class="actions"><button class="btn danger" data-action="delete-story" data-id="${s.id}">${icon('trash')}Delete</button><button class="btn" data-action="draft-variants" data-id="${s.id}">Try three versions ${icon('arrow')}</button></div>`);if(s.audioId){const expectedEpoch=recordEpoch;try{let blob=await audioOp('get',s.audioId);if(blob&&expectedEpoch===recordEpoch&&$('#saved-audio')?.dataset.storyId===s.id){const url=URL.createObjectURL(blob);objectUrls.push(url);$('#saved-audio').innerHTML=`<audio class="audio" controls src="${url}"></audio><a class="text-btn" href="${url}" download="storybank-recording.webm">Download recording</a>`;}}catch{modalError('Audio could not be loaded from this browser.');}}}
function chooseStory(){openModal('Start with your experience.','Pick a story to try three template previews.',state.stories.length?state.stories.map(s=>`<button class="draft-item" data-action="draft-variants" data-id="${s.id}" style="border:1px solid var(--line)"><strong>${esc(s.title)}</strong><small>${s.demo?'Demo example · ':''}${s.body?'Ready to write':'Add a transcript first'}</small></button>`).join(''):`<div class="empty"><p>You haven’t saved a story yet. Tell us about something that happened in your work recently.</p><button class="btn" data-action="new-story">Tell my story</button></div>`);}
function makeVariants(id){let s=state.stories.find(x=>x.id===id);if(!s)throw Error('Story not found.');const variants=createVariants(s,state.style).map(d=>({...d,styleVersion:state.styleVersion,demo:s.demo}));state.drafts.unshift(...variants);selectedDraft=variants[0].id;save();closeModal();location.hash=`studio/${selectedDraft}`;shell();toast('Three template previews are ready. Edit one, then tell us what feels right.');}
function updatePreview(){const d=state.drafts.find(x=>x.id===selectedDraft);if(!d)return;const text=plainText(d.body);if($('#post-body'))$('#post-body').innerHTML=preview==='rich'?esc(d.body).replace(/\*\*(.*?)\*\*/gs,'<strong>$1</strong>').replace(/(?<!\*)\*([^*]+)\*(?!\*)/gs,'<em>$1</em>'):esc(text);if($('#character-count')){$('#character-count').textContent=`${text.length.toLocaleString()} / 3,000 characters`;$('#character-count').classList.toggle('danger-text',text.length>3000);}if($('#plan-btn'))$('#plan-btn').disabled=!d.approval;if($('#approve-btn'))$('#approve-btn').innerHTML=`${icon('check')}${d.approval?'Version reviewed':'Approve this version'}`;if($('#approval-note'))$('#approval-note').textContent=d.approval?'This exact plain-text version has been reviewed. Editing it requires a new review.':'Nothing publishes automatically. Approval is stored locally for this exact version.';}
function feedbackModal(id){openModal('What feels like you?','Your feedback belongs only to your personal writing profile.',`<form id="feedback-form" data-draft-id="${id}"><label class="field"><span>How did this version feel?</span><select name="rating"><option value="like">I like this direction</option><option value="dislike">It needs a different direction</option><option value="edited">I edited it to sound more like me</option></select></label><div class="field"><span>What should change in future drafts?</span>${[['shorter','Use shorter paragraphs'],['natural','Start with the story, not a headline'],['headline','Start with my story title'],['no_question','Don’t add a closing question'],['question','End with an open question']].map(([k,v])=>`<label class="check"><input type="checkbox" name="reason" value="${k}">${v}</label>`).join('')}</div><label class="field"><span>Tell us why, in your own words</span><textarea name="note" maxlength="1500" placeholder="What did you like, dislike, or edit? What should we remember?"></textarea><small>Free-text feedback is saved for your profile. Interpreting it automatically needs a connected AI model.</small></label><div class="actions"><button class="btn secondary" type="button" data-action="close-modal">Cancel</button><button class="btn" type="submit">Review my changes ${icon('arrow')}</button></div></form>`);}
let pendingStyle=null;
function showProposal(feedback){const proposal=proposeStyle(state,feedback);pendingStyle={...proposal,expectedVersion:state.styleVersion,ownerId:state.ownerId};openModal('Make these your preferences?','Nothing changes until you apply this update.',`${proposal.changes.length?`<div class="style-summary"><ul>${proposal.changes.map(c=>`<li>${esc(c)}</li>`).join('')}</ul></div>`:notice('Your feedback has been saved. No structured style changes were selected. You can update preferences manually under Your voice.')} ${proposal.note?`<p class="spaced"><strong>Your note:</strong> ${esc(proposal.note)}</p>`:''}<p class="preview-note">Applies only to future previews in this workspace. Existing drafts stay untouched. Your free-text note is saved, not automatically interpreted.</p><div class="actions"><button class="btn secondary" data-action="close-modal">Keep current style</button>${proposal.changes.length?'<button class="btn" data-action="apply-proposal">Apply to my profile</button>':''}</div>`);}
function planningModal(){const d=state.drafts.find(d=>d.id===selectedDraft);if(!d?.approval)throw Error('Review and approve this exact version first.');const tomorrow=new Date(Date.now()+86400000);tomorrow.setHours(10,0,0,0);const value=new Date(tomorrow.getTime()-tomorrow.getTimezoneOffset()*60000).toISOString().slice(0,16);openModal('Make a little space for this story.','Choose when you would like to share it.',`${notice('This is a local plan, not an automatic post or reminder. Use LinkedIn’s own scheduler to arrange real publishing.','amber')}<form id="plan-form" data-draft-id="${d.id}"><label class="field"><span>Date and time</span><input type="datetime-local" name="time" value="${value}" required><small>Your browser time zone: ${esc(Intl.DateTimeFormat().resolvedOptions().timeZone)}. Saved as an exact UTC instant.</small></label><div class="actions"><button type="button" class="btn secondary" data-action="close-modal">Cancel</button><button type="submit" class="btn">Save my plan ${icon('calendar')}</button></div></form>`);}
function download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function exportWorkspace(){download('storybank-workspace.json',JSON.stringify({...state,exportedAt:new Date().toISOString(),notice:'Local prototype export; audio files are separate. No credentials or connected account data.'},null,2),'application/json');toast('Text workspace exported. Recordings must be downloaded separately.');}
function privacy(){openModal('Your data stays here.','A local prototype, not a connected SaaS account.',`<p>Stories, drafts, references, and feedback are saved in this browser. Recordings are saved in its IndexedDB. Nothing is sent to LinkedIn or an AI provider.</p><p>This prototype does not offer authenticated user isolation or encrypted browser storage. Do not use sensitive information on a shared device.</p><p>Export or delete your data in Settings. A production account system and integrations remain to be implemented.</p><div class="actions"><button class="btn" data-action="open-settings">Open settings ${icon('arrow')}</button></div>`);}
const actions={
 'close-modal':()=>closeModal(),
 onboard:()=>{onboardStep=0;onboard();},
 'onboard-next':()=>{if(onboardStep===1){state.profile.name=$('#onboard-name').value.trim();state.profile.headline=$('#onboard-headline').value.trim();save();}if(onboardStep<2){onboardStep++;onboard();}else{state.onboarded=true;save();closeModal();shell();$('#quick-note')?.focus();}},
 'onboard-back':()=>{onboardStep--;onboard();},
 'finish-examples':()=>{state.onboarded=true;loadExamples();closeModal();location.hash='stories';shell();},
 'load-examples':()=>loadExamples(),
 'quick-save':()=>newStoryModal($('#quick-note').value),
 'new-story':()=>newStoryModal(),
 voice:()=>newStoryModal('',true),
 prompt:()=>{const field=$('#quick-note');field.value='I learned this the hard way: ';field.focus();field.setSelectionRange(field.value.length,field.value.length);},
 record:()=>record(),
 'stop-record':()=>stopRecording(),
 'view-story':el=>viewStory(el.dataset.id),
 'draft-variants':el=>makeVariants(el.dataset.id),
 'choose-story':()=>chooseStory(),
 'select-draft':el=>{selectedDraft=el.dataset.id;closeModal();location.hash=`studio/${selectedDraft}`;shell();},
 'format-bold':()=>format('**'),
 'format-italic':()=>format('*'),
 feedback:el=>feedbackModal(el.dataset.id),
 'apply-proposal':()=>{if(!pendingStyle)throw Error('No changes are waiting.');if(pendingStyle.expectedVersion!==state.styleVersion||pendingStyle.ownerId!==state.ownerId)throw Error('Your profile changed after this suggestion. Close this window and review your feedback again.');applyStyle(state,pendingStyle.style,'Applied my writing feedback');pendingStyle=null;save();closeModal();toast('Your profile is updated. New previews will use these preferences.');if(route==='style')shell();},
 approve:async()=>{const d=state.drafts.find(x=>x.id===selectedDraft);if(d.demo)throw Error('This is a demo example. Save your own story before approving a personal post.');validateApproval(d);const snapshot=d.body;const hash=await fingerprint(snapshot);if(d.body!==snapshot||!d.reviewed||!state.drafts.includes(d))throw Error('The draft or its review changed. Review it again.');d.approval={hash,at:new Date().toISOString()};save();updatePreview();toast('This exact version is reviewed. You can now plan a date.');},
 plan:()=>planningModal(),
 copy:async()=>{const d=state.drafts.find(x=>x.id===selectedDraft);if(d.demo)toast('Copied sample text. Do not present the example as your own experience.');try{await navigator.clipboard.writeText(plainText(d.body));toast(d.demo?'Sample text copied. Replace it with your own experience.':'Plain text copied. Formatting markers were removed.');}catch{download('storybank-post.txt',plainText(d.body));toast('Clipboard unavailable. Downloaded the plain-text post instead.');}},
 'export-draft':()=>{const d=state.drafts.find(x=>x.id===selectedDraft);download('storybank-post.txt',(d.demo?'DEMO EXAMPLE — not your personal experience\n\n':'')+plainText(d.body));},
 'add-reference':()=>openModal('Who inspires your writing?','Keep the useful qualities. Keep your own voice.',`<form id="reference-form"><label class="field"><span>Name</span><input name="name" required maxlength="80" placeholder="The person’s name"></label><label class="field"><span>LinkedIn or website link (optional)</span><input name="url" type="url" placeholder="https://…"><small>Saved as a bookmark only. We do not read or scrape this page.</small></label><label class="field"><span>What do you like about their writing?</span><textarea name="notes" maxlength="800" placeholder="For example: a short opening, one specific lesson, and a calm tone."></textarea><small>Describe broad traits in your own words. Don’t paste someone else’s posts without permission.</small></label><div class="actions"><button type="button" class="btn secondary" data-action="close-modal">Cancel</button><button class="btn" type="submit">Add to my profile</button></div></form>`),
 'delete-reference':el=>{state.references=state.references.filter(r=>r.id!==el.dataset.id);applyStyle(state,state.style,'Removed a reference bookmark');save();shell();},
 'save-style':()=>{const style={tone:$('#style-tone').value,structure:$('#style-structure').value,traits:[...document.querySelectorAll('[data-trait].active')].map(x=>x.dataset.trait),avoid:$('#style-avoid').value.trim()};applyStyle(state,style,'Updated my preferences');save();shell();toast('Your personal writing profile is saved.');},
 'restore-style':el=>{const h=state.styleHistory.find(h=>h.version===Number(el.dataset.version));if(!h)return;openModal(`Restore version ${h.version}?`,'This creates a new version, so your history stays intact.',`<p>Future previews will use these earlier preferences. Existing drafts are not changed.</p><div class="actions"><button class="btn secondary" data-action="close-modal">Cancel</button><button class="btn" data-action="confirm-restore" data-version="${h.version}">Restore preferences</button></div>`);},
 'confirm-restore':el=>{const h=state.styleHistory.find(h=>h.version===Number(el.dataset.version));applyStyle(state,h.style,`Restored version ${h.version}`);save();closeModal();shell();toast('Earlier preferences restored as a new version.');},
 'reset-style':()=>openModal('Start with a clean style?','Your stories, drafts, references, and feedback will remain.',`<p>This resets tone and structure to the starting preferences. Your current version stays in history.</p><div class="actions"><button class="btn secondary" data-action="close-modal">Cancel</button><button class="btn" data-action="confirm-reset">Reset preferences</button></div>`),
 'confirm-reset':()=>{applyStyle(state,freshState().style,'Reset to starting preferences');save();closeModal();shell();},
 'export-skill':()=>{download('storybank-personal-writing-profile.md',exportSkill(state),'text/markdown');toast('Your personal writing profile is downloaded.');},
 'save-profile':()=>{state.profile.name=$('#profile-name').value.trim();state.profile.headline=$('#profile-headline').value.trim();save();shell();toast('Profile saved on this browser.');},
 'export-workspace':()=>exportWorkspace(),
 'prev-month':()=>{calendarMonth=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth()-1,1);shell();},
 'next-month':()=>{calendarMonth=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth()+1,1);shell();},
 'cancel-plan':el=>{const p=state.plans.find(p=>p.id===el.dataset.id);if(p){p.status='cancelled';p.reason='Cancelled by the owner.';save();shell();toast('Plan cancelled. Nothing was posted.');}},
 'delete-story':el=>{const id=el.dataset.id;openModal('Delete this story?','This also removes its drafts and local plans.',`<p>Any recording for this story will be deleted from this browser. Download it first if you want a copy.</p><div class="actions"><button class="btn secondary" data-action="close-modal">Keep story</button><button class="btn danger" data-action="confirm-delete-story" data-id="${id}">Delete story and drafts</button></div>`);},
 'confirm-delete-story':async el=>{const s=state.stories.find(s=>s.id===el.dataset.id);if(s?.audioId)await audioOp('delete',s.audioId);deleteStory(state,el.dataset.id);save();if(storageFailed)throw Error('Browser storage could not confirm deletion. Clear this site’s browser data manually.');closeModal();shell();toast('Story, recording, drafts, and plans deleted from this browser.');},
 'add-transcript':el=>{const s=state.stories.find(s=>s.id===el.dataset.id);openModal('Edit your transcript.','Use only what you actually said or know.',`<form id="transcript-form" data-id="${s.id}"><label class="field"><span>Transcript or notes</span><textarea name="body" required maxlength="12000" rows="7">${esc(s.body)}</textarea></label><p class="preview-note">Existing drafts retain their original source snapshot. Create new previews to use this edited transcript.</p><div class="actions"><button type="button" class="btn secondary" data-action="close-modal">Cancel</button><button type="submit" class="btn">Save transcript</button></div></form>`);},
 'delete-workspace':()=>openModal('Delete everything from this browser?','This cannot be undone. Export anything you want to keep first.',`<form id="delete-form"><p>Stories, recordings, drafts, plans, feedback, and your personal writing profile will be removed. This does not affect exported copies.</p><label class="field"><span>Type DELETE to confirm</span><input name="confirm" autocomplete="off" required></label><div class="actions"><button type="button" class="btn secondary" data-action="close-modal">Keep workspace</button><button type="submit" class="btn danger">Delete my local workspace</button></div></form>`),
 privacy:()=>privacy(),
 'open-settings':()=>{closeModal();location.hash='settings';},
 'integration-details':()=>openModal('Connections are the next phase.','No fake sign-in or publishing switches here.',`<p>Before a public launch, StoryBank needs a real account system, server-enforced personal data boundaries, a database, approved AI and transcription providers, and privacy/deletion operations.</p><p>LinkedIn sign-in and publishing need separate permissions. Automatic scheduling remains disabled until the exact API use case is approved.</p><p>No LinkedIn passwords should ever enter this app. Any future OAuth tokens belong in protected server storage, not this browser or a writing prompt.</p><div class="actions"><button class="btn" data-action="close-modal">Got it</button></div>`)
};
function loadExamples(){if(state.stories.some(s=>s.demo)){toast('Your example stories are already on the shelf.');return;}state.stories.unshift(...examples());save();shell();toast('Two labelled demo stories added. They are not your personal experiences.');}
function format(mark){const input=$('#draft-body');const a=input.selectionStart,b=input.selectionEnd;if(a===b){toast('Select some text first.');input.focus();return;}input.setRangeText(mark+input.value.slice(a,b)+mark,a,b,'select');input.dispatchEvent(new Event('input',{bubbles:true}));input.focus();}
document.addEventListener('click',async event=>{const target=event.target.closest('[data-action],[data-filter],[data-preview],[data-trait]');if(!target||target.disabled)return;try{if(target.dataset.action){await actions[target.dataset.action]?.(target);}else if(target.dataset.filter){filter=target.dataset.filter;shell();}else if(target.dataset.preview){preview=target.dataset.preview;shell();}else if(target.dataset.trait){target.classList.toggle('active');target.setAttribute('aria-pressed',String(target.classList.contains('active')));}}catch(e){modalError(e.message||'Something did not complete. Please try again.');}});
document.addEventListener('input',event=>{if(event.target.id==='draft-body'){const d=state.drafts.find(d=>d.id===selectedDraft);if(!d)return;const hadApproval=!!d.approval;editDraft(state,d.id,event.target.value);if($('#reviewed'))$('#reviewed').checked=false;save();updatePreview();if(hadApproval)toast('Review cleared and any active plan cancelled because the draft changed.');}});
document.addEventListener('change',event=>{if(event.target.id==='reviewed'){const d=state.drafts.find(d=>d.id===selectedDraft);if(!d)return;d.reviewed=event.target.checked;if(!d.reviewed){d.approval=null;for(const p of state.plans)if(p.draftId===d.id&&p.status==='planned'){p.status='cancelled';p.reason='Review confirmation withdrawn.';}}save();updatePreview();}});
document.addEventListener('submit',async event=>{event.preventDefault();const form=event.target;const data=new FormData(form);const submit=form.querySelector('[type=submit]');if(submit)submit.disabled=true;try{
 if(form.id==='story-form'){if(mediaRecorder?.state==='recording')throw Error('Stop the recording before saving.');const title=String(data.get('title')||'').trim(),body=String(data.get('body')||'').trim();if(!title||(!body&&!recordedBlob))throw Error('Add a title and a story or recording.');if(!data.get('rights'))throw Error('Confirm you have permission to use this story.');let audioId=null;if(recordedBlob){if(recordedBlob.size>30*1024*1024)throw Error('Recording is too large. Keep it under 30 MB.');audioId=uid('audio');await audioOp('put',audioId,recordedBlob);}state.stories.unshift({id:uid('story'),title,body,tag:String(data.get('tag')),rights:true,demo:false,audioId,createdAt:new Date().toISOString()});save();if(storageFailed){if(audioId)await audioOp('delete',audioId);state.stories.shift();throw Error('Browser storage could not save this story. Export your existing workspace and free space first.');}closeModal();location.hash='stories';shell();toast('Story saved. When you’re ready, shape it into a post.');}
 if(form.id==='reference-form'){if(state.references.length>=MAX_REFERENCES)throw Error('You can save up to 15 references.');const ref=normalizeReference(Object.fromEntries(data));state.references.push(ref);applyStyle(state,state.style,'Added a personal reference bookmark');save();closeModal();shell();toast('Reference saved to your personal profile. No content was imported.');}
 if(form.id==='feedback-form'){const reasons=data.getAll('reason');if(reasons.includes('natural')&&reasons.includes('headline'))throw Error('Choose either story first or title first.');if(reasons.includes('question')&&reasons.includes('no_question'))throw Error('Choose whether to include or omit the closing question.');const feedback=addFeedback(state,form.dataset.draftId,{rating:data.get('rating'),reasons,note:data.get('note')});save();showProposal(feedback);}
 if(form.id==='plan-form'){const draftId=form.dataset.draftId;const d=state.drafts.find(d=>d.id===draftId);const hash=await fingerprint(d.body);const localValue=String(data.get('time'));const parsed=new Date(localValue);if(!Number.isFinite(parsed.getTime()))throw Error('Choose a valid date and time.');const reconstructed=new Date(parsed.getTime()-parsed.getTimezoneOffset()*60000).toISOString().slice(0,16);if(reconstructed!==localValue)throw Error('That local time does not exist due to a clock change. Choose a different time.');planDraft(state,draftId,parsed.toISOString(),hash);save();closeModal();calendarMonth=new Date(parsed.getFullYear(),parsed.getMonth(),1);location.hash='calendar';shell();toast('Local plan saved. It will not post or send a reminder.');}
 if(form.id==='transcript-form'){const s=state.stories.find(s=>s.id===form.dataset.id);s.body=String(data.get('body')).trim();save();closeModal();shell();toast('Transcript saved. Future previews will use it.');}
 if(form.id==='delete-form'){if(data.get('confirm')!=='DELETE')throw Error('Type DELETE exactly to confirm.');await audioOp('clear');localStorage.removeItem(STORAGE_KEY);state=ensureProfile(freshState());state.onboarded=true;save();if(storageFailed)throw Error('Deletion could not be fully confirmed. Clear this site’s browser data manually.');closeModal();location.hash='stories';shell();toast('Your previous workspace and recordings were deleted. A blank workspace is ready.');}
 }catch(e){modalError(e.message||'This action could not be completed.');}finally{if(submit?.isConnected)submit.disabled=false;}});
document.addEventListener('keydown',e=>{if(!$('.modal'))return;if(e.key==='Escape'){e.preventDefault();closeModal();}if(e.key==='Tab'){const elements=[...$('.modal').querySelectorAll('button,input,textarea,select,a[href]')].filter(x=>!x.disabled);const first=elements[0],last=elements.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
window.addEventListener('hashchange',()=>{if(location.hash==='#main'){$('#main')?.focus();return;}if($('.modal'))closeModal();shell();window.scrollTo(0,0);});
window.addEventListener('beforeunload',()=>{stopRecording();});
window.addEventListener('storage',e=>{if(e.key===STORAGE_KEY){if($('.modal'))closeModal();pendingStyle=null;state=ensureProfile(readState(localStorage));shell();toast('Workspace updated from another tab.');}});
save();shell();if(!state.onboarded)onboard();
